import{_ as e,o as a,c as i,ag as s}from"./chunks/framework.DEqXEGcv.js";const p=JSON.parse('{"title":"thegent Testing Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/TESTING.md","filePath":"guides/TESTING.md","lastUpdated":1771159865000}'),n={name:"guides/TESTING.md"};function o(r,t,l,d,h,c){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="thegent-testing-guide" tabindex="-1">thegent Testing Guide <a class="header-anchor" href="#thegent-testing-guide" aria-label="Permalink to &quot;thegent Testing Guide&quot;">​</a></h1><p>This guide defines the testing philosophy and standards for <code>thegent</code>.</p><h2 id="_1-test-pyramid-targets" tabindex="-1">1. Test Pyramid Targets <a class="header-anchor" href="#_1-test-pyramid-targets" aria-label="Permalink to &quot;1. Test Pyramid Targets&quot;">​</a></h2><p>We maintain a strict test distribution to ensure fast feedback and high reliability:</p><ul><li><strong>Unit Tests (70%)</strong>: Fast, isolated tests for individual functions and classes. Found in <code>tests/</code> with <code>@pytest.mark.unit</code>.</li><li><strong>Integration Tests (20%)</strong>: Testing interaction between components (e.g., runners and registries). Marked with <code>@pytest.mark.integration</code>.</li><li><strong>E2E Tests (10%)</strong>: End-to-end CLI/MCP flows. Marked with <code>@pytest.mark.e2e</code>.</li></ul><p>Use <code>task test:pyramid</code> to validate the current distribution.</p><h2 id="_2-methodology" tabindex="-1">2. Methodology <a class="header-anchor" href="#_2-methodology" aria-label="Permalink to &quot;2. Methodology&quot;">​</a></h2><h3 id="test-first-tdd" tabindex="-1">Test-First (TDD) <a class="header-anchor" href="#test-first-tdd" aria-label="Permalink to &quot;Test-First (TDD)&quot;">​</a></h3><p>Implementations should follow the Red-Green-Refactor loop. Every new feature requires a corresponding test file <strong>before</strong> implementation.</p><h3 id="fr-traceability" tabindex="-1">FR Traceability <a class="header-anchor" href="#fr-traceability" aria-label="Permalink to &quot;FR Traceability&quot;">​</a></h3><p>Every test function <strong>must</strong> reference a functional requirement ID using the <code>@trace</code> tag or marker.</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@pytest.mark.requirement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FR-CORE-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> test_core_functionality</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">():</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # ...</span></span></code></pre></div><h2 id="_3-tooling" tabindex="-1">3. Tooling <a class="header-anchor" href="#_3-tooling" aria-label="Permalink to &quot;3. Tooling&quot;">​</a></h2><ul><li><strong>Pytest</strong>: Primary test runner.</li><li><strong>pytest-xdist</strong>: Used for parallel execution (<code>task test</code>).</li><li><strong>Coverage</strong>: We target &gt; 80% line coverage.</li><li><strong>Traceability Validator</strong>: <code>task quality</code> runs <code>scripts/traceability-validator.sh</code>.</li></ul><h2 id="_4-canonical-naming" tabindex="-1">4. Canonical Naming <a class="header-anchor" href="#_4-canonical-naming" aria-label="Permalink to &quot;4. Canonical Naming&quot;">​</a></h2><p>Test files must be named based on the <strong>concern</strong> they test, not the level.</p><ul><li>✅ <code>tests/test_adapters.py</code></li><li>❌ <code>tests/test_unit_adapters.py</code></li></ul>`,17)])])}const u=e(n,[["render",o]]);export{p as __pageData,u as default};
